cssCode:
.gooey-container {
  width: 100%; height: 100%; position: relative; background: #000;
  filter: contrast(30); display: flex; align-items: center; justify-content: center;
  overflow: hidden; touch-action: none;
}
.center-blob {
  width: 120px; height: 120px; background: #ff007f;
  border-radius: 50%; filter: blur(20px); position: absolute;
  animation: pulseBlob 3s infinite alternate ease-in-out;
}
.cursor-blob {
  width: 80px; height: 80px; background: #00d2ff;
  border-radius: 50%; filter: blur(20px); position: absolute;
  pointer-events: none; transform: translate(-50%, -50%);
  transition: transform 0.1s;
}
@keyframes pulseBlob {
  0% { transform: scale(1); }
  100% { transform: scale(1.3); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:#000;overflow:hidden;touch-action:none;';

const wrap = document.createElement('div');
wrap.className = 'gooey-container';

const center = document.createElement('div');
center.className = 'center-blob';

const cursor = document.createElement('div');
cursor.className = 'cursor-blob';

wrap.appendChild(center);
wrap.appendChild(cursor);
c.appendChild(wrap);

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  cursor.style.left = `${x}px`;
  cursor.style.top = `${y}px`;
});
